// Program.cs — policy defaults + distributed store option
builder.Services.AddOutputCache(options =>
{
    options.AddPolicy("catalog", policy => policy
        .Expire(TimeSpan.FromSeconds(30))
        .StaleWhileRevalidate(TimeSpan.FromSeconds(60))
        .SetVaryByQuery("page", "sort")
        .Cache();                       // public, shareable — no per-user variance

    options.AddPolicy("account", policy => policy
        .Expire(TimeSpan.FromSeconds(10))
        .Tag("account"));
});
// builder.Services.AddStackExchangeRedisOutputCache(o => o.Configuration = redisConn); // multi-instance

var app = builder.Build();
app.UseOutputCache();

// Public, expensive read — cached response, tagged for eviction
app.MapGet("/api/products/{id:int}", async (int id, ProductDb db, CancellationToken ct) =>
{
    var dto = await db.Products.AsNoTracking()
        .Where(p => p.Id == id)
        .Select(p => new ProductDto(p.Id, p.Name, p.Price))
        .FirstOrDefaultAsync(ct);
    return dto is null ? Results.NotFound() : Results.Ok(dto);
})
.WithName("GetProduct")
.RequireRateLimiting("read")
.Cache(policy => policy.Expire(TimeSpan.FromSeconds(60))
                       .Tag($"product-{id}"));      // included below via route value

